package com.novacommerce.order.infrastructure.client; import com.novacommerce.order.api.error.OrderException; import java.math.BigDecimal; import java.util.*; import org.springframework.beans.factory.annotation.Qualifier; import org.springframework.core.ParameterizedTypeReference; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient;
@Component public class CatalogClient{private final RestClient client;public CatalogClient(@Qualifier("catalogRestClient")RestClient c){client=c;}public List<Variant>variants(Collection<UUID>ids){try{return client.get().uri(b->{var x=b.path("/api/v1/catalog/variants");ids.stream().sorted().forEach(id->x.queryParam("ids",id));return x.build();}).retrieve().body(new ParameterizedTypeReference<List<Variant>>(){});}catch(Exception e){throw new OrderException(HttpStatus.SERVICE_UNAVAILABLE,"CATALOG_UNAVAILABLE","Catalog is temporarily unavailable");}}public record Price(BigDecimal amount,String currency){}public record Variant(UUID variantId,UUID productId,String productName,String productSlug,String variantName,String sku,Map<String,String>attributes,Price price){}}
